void mainImage(out vec4 couleurFragment, vec2 coordFragment) {
    vec2 resolutionEcran = iResolution.xy;
    vec3 positionRayon = vec3(0.0);
    float distanceParcourueTotal = 0.0;
    float distanceEstimationSurface = 0.0;
    float rayonLogPolar = 0.0;
    float angleRotationCamera = iTime * 0.5;

    mat2 matriceRotationXZ = mat2(
        cos(angleRotationCamera), sin(angleRotationCamera),
        -sin(angleRotationCamera), cos(angleRotationCamera)
    );

    for (int etapeMarchage = 0; etapeMarchage < 64; etapeMarchage++) {
        positionRayon = vec3((coordFragment + coordFragment - resolutionEcran) / resolutionEcran.y, 1.0) * distanceParcourueTotal;
        positionRayon.z -= 3.0;
        positionRayon.xy *= matriceRotationXZ;

        rayonLogPolar = length(positionRayon.xy);

        float anglePolaire = atan(positionRayon.y, positionRayon.x);
        float coordonneeLogarithmique = log(rayonLogPolar) - iTime;
        vec2 grilleLogPolaire = fract(vec2(anglePolaire, coordonneeLogarithmique) / 0.8) - 0.5;

        distanceEstimationSurface = length(grilleLogPolaire) * rayonLogPolar - 0.05;

        float delimitationSphereEnglobante = length(positionRayon) - 2.0;
        distanceParcourueTotal += max(distanceEstimationSurface, delimitationSphereEnglobante) * 0.5;
    }

    uvec2 coordonneePixelEntiere = uvec2(coordFragment);
    uint graineAleatoire = coordonneePixelEntiere.x + coordonneePixelEntiere.y * uint(resolutionEcran.x) + uint(iFrame) * uint(resolutionEcran.x * resolutionEcran.y);
    graineAleatoire *= 916533289u;

    float bruitDither = float(graineAleatoire) / 4294967295.0 * 0.1;

    vec4 couleurTeinte = (cos(iTime + positionRayon.z + vec4(0.0, 2.0, 4.0, 0.0)) + 1.0);
    float attenuationDistance = 1.0 / (1.0 + distanceParcourueTotal * distanceParcourueTotal * 0.1);

    couleurFragment = couleurTeinte * attenuationDistance + bruitDither;
}
